<template><section class="space-y-6"><div class="flex items-center justify-between"><h1 class="text-2xl font-semibold">Staff</h1><button class="rounded bg-primary px-4 py-2 text-primary-foreground" @click="invite">Invite staff</button></div><p v-if="message" class="text-sm">{{ message }}</p><div class="overflow-auto rounded-xl bg-background shadow"><table class="w-full text-left text-sm"><thead><tr class="border-b"><th class="p-4">Name</th><th class="p-4">Email</th><th class="p-4">Status</th><th class="p-4">Permissions</th></tr></thead><tbody><tr v-for="user in users" :key="user.id" class="border-b"><td class="p-4">{{ user.name }}</td><td class="p-4">{{ user.email }}</td><td class="p-4">{{ user.active ? 'Active' : 'Inactive' }}</td><td class="p-4">{{ user.effectivePermissions?.length || 0 }}</td></tr></tbody></table></div></section></template>
<script setup lang="ts">import { onMounted, ref } from "vue"; import { authHttp } from "@/auth"; const users = ref<any[]>([]); const message = ref(""); const load = async () => { const { data } = await authHttp.get("/api/staff/users"); users.value = Array.isArray(data) ? data : data.users || []; }; const invite = async () => { message.value = "Use the API to provide an email, name, and role."; }; onMounted(load);</script>
